//! The corpus: every document the record covers, declared once, generated in code.
//!
//! A corpus document is produced by the engine's own writer — [`document_engine::operation`] — from
//! the steps declared here. A step may chain onto the file the previous step produced, because it is
//! the writer's output that is recorded, not a sample document. No binary sample document is
//! committed: the one picture the corpus embeds is generated by [`crate::engine::picture`].
//!
//! # What the corpus covers, and what it cannot
//!
//! Word: headings at all three levels, paragraphs, a bulleted and an ordered list, a table with
//! headers and rows, an embedded picture, a link, a page break, a table of contents, a running
//! header and footer carrying a page-number and a page-count token, and a paragraph footnote —
//! [`REPORT`], [`PICTURE`], [`BLANK_PAGE`] and [`HEADER_ONLY_PAGE`].
//!
//! PowerPoint: title and body frames, a table, a placed picture, speaker notes and more than one
//! slide — [`DECK`].
//!
//! Excel: several sheets, values of several kinds, number formats and merged ranges — [`WORKBOOK`].
//!
//! The writer cannot produce these shapes, and the record therefore says nothing about them:
//!
//! - a Word text box, a comment or a tracked change: `create` writes none, and the edit path's
//!   comment and revision handling is a different body of work;
//! - a Word page with no ink at all: reachable only as two consecutive page breaks, which is what
//!   [`BLANK_PAGE`] and [`HEADER_ONLY_PAGE`] declare;
//! - a created Word document that names a font: its document defaults are empty and its font table
//!   has no entries, so every Word record is laid out in the reference's own default face — stated
//!   per document in the record's `faces` section, never left to be read as fidelity;
//! - an Excel date, time or currency *type*: a cell is text, a number or a boolean, so a date is a
//!   serial number with a date number format, and a currency amount is a number with a currency
//!   format — [`WORKBOOK`]'s edit step states both, in formats that fit a default column, because a
//!   created workbook states no column widths and a wider number is drawn as `###`;
//! - an Excel page setup of any kind: a created workbook states no paper, no margins and no column
//!   widths, so its pages are decided by the reference's pinned locale and default paper, which is
//!   what makes [`crate::LOCALE`] part of the identity rather than a footnote;
//! - a PowerPoint hidden slide or a slide transition or animation: `create` writes neither, and a
//!   PDF shows a slide's final state only;
//! - a slide background supplied as an image: `create` states the reference's white fill, and the
//!   ink rule counts an image as ink, so such a background would be read as a page's own ink.
//!
//! The corpus is bounded: six documents and seven operations, stated by [`documents`] and printed by
//! every run.

use crate::Format;

/// One step of a document's chain, shared with the comparison's fixed set.
pub use crate::chain::Step;

/// One page the corpus declares carries no ink, with the reason it is empty.
pub struct BlankPage {
    /// The page's number, counted from one.
    pub page: u32,
    /// Why it is empty. Declared here rather than guessed at run time: a page the run finds empty
    /// and the corpus does not declare fails the run.
    pub reason: &'static str,
}

/// One document the record covers.
pub struct Document {
    /// The record's name for it: `<family>/<name>`, which is also its directory under
    /// `record/documents/`.
    pub id: &'static str,
    /// The family it belongs to.
    pub format: Format,
    /// The operations that produce it, in order.
    pub steps: &'static [Step],
    /// The pages the corpus declares empty.
    pub blank: &'static [BlankPage],
    /// What the reference's export does not show, so that its silence is never later read as a
    /// mandate.
    pub not_shown: &'static [&'static str],
    /// The numbers the document prints from the engine's own layout pass rather than from the
    /// reference, so that a visibly self-inconsistent recorded document is never read as a claim
    /// about those numbers.
    pub engine_computed: &'static [&'static str],
}

impl Document {
    /// The name the engine writes under: the id's own last segment.
    pub fn name(&self) -> &'static str {
        self.id.rsplit_once('/').map_or(self.id, |(_, name)| name)
    }

    /// The base name one step writes under. Every step has its own, because the engine never
    /// overwrites and a step that read the previous one's file would otherwise collide with it.
    pub fn base_name(&self, step: usize) -> String {
        format!("{}-{}", self.name(), step + 1)
    }
}

/// Every document the record covers, in the order the record states them.
pub fn documents() -> &'static [Document] {
    &[
        REPORT,
        PICTURE,
        BLANK_PAGE,
        HEADER_ONLY_PAGE,
        DECK,
        WORKBOOK,
    ]
}

/// The one generated picture a chain embeds.
pub const PICTURE_FILE: crate::chain::Asset = crate::chain::Asset {
    name: "picture",
    extension: "png",
    bytes: crate::engine::picture,
};

/// The generated files the corpus embeds, written once per run.
pub const ASSETS: &[crate::chain::Asset] = &[PICTURE_FILE];

/// A Word report: every shape the writer can put in a document, on two pages.
pub const REPORT: Document = Document {
    id: "docx/report",
    format: Format::Docx,
    steps: &[Step {
        operation: "create",
        values: || {
            serde_json::json!({
                "format": "docx",
                "content": [
                    {"type": "heading", "text": "Quarterly report", "level": 1},
                    {"type": "paragraph", "text": "Every page in this record is the writer's own output, laid out by the outside reference. This paragraph is long enough that the reference has to break it across several lines, which is what makes a page boundary worth recording at all. The words after it are ordinary prose."},
                    {"type": "heading", "text": "Revenue by region", "level": 2},
                    {"type": "list", "items": ["North", "South", "East", "West"]},
                    {"type": "paragraph", "text": "The same regions, in the order the report reads them:"},
                    {"type": "list", "items": ["North", "South", "East", "West"], "ordered": true},
                    {"type": "heading", "text": "Detail", "level": 3},
                    {"type": "table", "headers": ["Region", "Revenue", "Growth"], "rows": [["North", "1 200", "4%"], ["South", "980", "2%"], ["East", "1 540", "7%"]]},
                    {"type": "image", "image": "$asset:picture", "width": 240, "height": 120},
                    {"type": "link", "text": "The full breakdown is published.", "url": "https://example.com/report"},
                    {"type": "page_break"},
                    {"type": "heading", "text": "Appendix", "level": 2},
                    {"type": "contents"},
                    {"type": "paragraph", "text": "A paragraph carrying a footnote.", "footnote": "The footnote's own text, on the page the reference gives it."}
                ],
                "header": "Quarterly report",
                "footer": "Page {page} of {pages}"
            })
        },
    }],
    blank: &[],
    not_shown: &[
        "commentary notes in the margin: the export states no comments, and a created document carries none",
        "hidden text: the export draws only visible text",
        "a link: it is drawn as its own text, with no target and no live link, so a page shows what the sentence says rather than where it goes",
        "a table of contents' page numbers: the reference does not update the field, it shows the cached numbers the engine's own layout pass wrote",
    ],
    engine_computed: &[
        "the page numbers a table of contents prints",
        "the page count a {pages} token shows",
    ],
};

/// A Word document whose only content is one embedded picture between two paragraphs.
pub const PICTURE: Document = Document {
    id: "docx/picture",
    format: Format::Docx,
    steps: &[Step {
        operation: "create",
        values: || {
            serde_json::json!({
                "format": "docx",
                "content": [
                    {"type": "paragraph", "text": "Above the picture."},
                    {"type": "image", "image": "$asset:picture"},
                    {"type": "paragraph", "text": "Below the picture."}
                ]
            })
        },
    }],
    blank: &[],
    not_shown: &[
        "a picture's own resolution: the export re-encodes what it was given, so a page shows the picture as the reference drew it, not as the bytes the writer embedded",
    ],
    engine_computed: &[],
};

/// A Word document with a page that carries no ink at all: two consecutive page breaks leave an
/// empty paragraph on a page of its own, and nothing is drawn on it.
pub const BLANK_PAGE: Document = Document {
    id: "docx/blank-page",
    format: Format::Docx,
    steps: &[Step {
        operation: "create",
        values: || {
            serde_json::json!({
                "format": "docx",
                "content": [
                    {"type": "paragraph", "text": "Before the empty page."},
                    {"type": "page_break"},
                    {"type": "page_break"},
                    {"type": "paragraph", "text": "After the empty page."}
                ]
            })
        },
    }],
    blank: &[BlankPage {
        page: 2,
        reason: "two consecutive page breaks leave an empty paragraph on a page of its own, and nothing is drawn on it",
    }],
    not_shown: &[
        "an empty page is drawn as an empty page: the export marks it in no way, so a page with no ink and a page that is missing look the same to a reader of the file",
    ],
    engine_computed: &[],
};

/// The same page breaks under a running header and footer: the page between them carries the
/// header's and the footer's ink and is therefore **not** blank.
pub const HEADER_ONLY_PAGE: Document = Document {
    id: "docx/header-only-page",
    format: Format::Docx,
    steps: &[Step {
        operation: "create",
        values: || {
            serde_json::json!({
                "format": "docx",
                "content": [
                    {"type": "paragraph", "text": "Before the page that carries only the header and the footer."},
                    {"type": "page_break"},
                    {"type": "page_break"},
                    {"type": "paragraph", "text": "After it."}
                ],
                "header": "Quarterly report",
                "footer": "Page {page} of {pages}"
            })
        },
    }],
    blank: &[],
    not_shown: &[
        "a running header and footer are drawn on every page, including one whose body is empty, so such a page is not blank",
    ],
    engine_computed: &["the page count a {pages} token shows"],
};

/// A widescreen deck: title and body frames, a table, a placed picture, speaker notes, three slides.
pub const DECK: Document = Document {
    id: "pptx/deck",
    format: Format::Pptx,
    steps: &[Step {
        operation: "create",
        values: || {
            serde_json::json!({
                "format": "pptx",
                "size": "widescreen",
                "content": [
                    {"type": "heading", "text": "Quarterly review", "level": 1},
                    {"type": "paragraph", "text": "Three workstreams this quarter."},
                    {"type": "list", "items": ["engine", "oracle", "renderer"]},
                    {"type": "heading", "text": "Revenue by region", "level": 1},
                    {"type": "table", "headers": ["Region", "Revenue"], "rows": [["North", "1 200"], ["South", "980"]]},
                    {"type": "image", "image": "$asset:picture", "width": 320, "height": 160},
                    {"type": "notes", "text": "Speaker notes for the second slide: they are not part of the pages this record holds."},
                    {"type": "heading", "text": "What comes next", "level": 1},
                    {"type": "paragraph", "text": "A renderer of our own, judged against this record."}
                ]
            })
        },
    }],
    blank: &[],
    not_shown: &[
        "speaker notes: the export asks for slides, not notes pages, so no notes page is drawn",
        "hidden slides: the export draws no slide the deck marks hidden, and a created deck marks none",
        "slide transitions and animations: a PDF shows a slide's final state only",
        "the notes master and any handout: neither is part of the export",
    ],
    engine_computed: &[],
};

/// A workbook with three sheets, values of several kinds, number formats and a merged range. The
/// edit step is the chain: a created workbook states one plain cell style, so a number format is
/// reachable only by editing the workbook the writer just made.
pub const WORKBOOK: Document = Document {
    id: "xlsx/workbook",
    format: Format::Xlsx,
    steps: &[
        Step {
            operation: "create",
            values: || {
                serde_json::json!({
                    "format": "xlsx",
                    "sheets": [
                        {
                            "name": "Summary",
                            "rows": [
                                ["Kind", "Value", "Note"],
                                ["text", "hello", "an inline string"],
                                ["number", 42, "a whole number"],
                                ["boolean", true, "a boolean"],
                                ["amount", 1234.5, "the edit step gives it a money format"],
                                ["share", 0.185, "the edit step gives it a percentage format"],
                                ["date", 46024, "the edit step gives it a date format"]
                            ],
                            "merges": ["A1:C1"]
                        },
                        {
                            "name": "Detail",
                            "rows": [
                                ["Region", "Revenue"],
                                ["North", 1200],
                                ["South", 980],
                                ["East", 1540]
                            ]
                        },
                        {
                            "name": "Notes",
                            "rows": [
                                ["A third sheet, so the workbook's pages are decided by more than one sheet's content."]
                            ]
                        }
                    ]
                })
            },
        },
        Step {
            operation: "xlsx_edit",
            values: || {
                serde_json::json!({
                    "input": "$previous",
                    "edits": [
                        {"op": "set_cell", "sheet": "Summary", "cell": "B5", "value": 1234.5, "number_format": "#,##0.00"},
                        {"op": "set_cell", "sheet": "Summary", "cell": "B6", "value": 0.185, "number_format": "0.0%"},
                        {"op": "set_cell", "sheet": "Summary", "cell": "B7", "value": 46024, "number_format": "dd/mm/yy"},
                        {"op": "set_cell", "sheet": "Detail", "cell": "B5", "value": {"formula": "=SUM(B2:B4)"}, "number_format": "#,##0.00"}
                    ]
                })
            },
        },
    ],
    blank: &[],
    not_shown: &[
        "cell comments: the export draws no comment indicator",
        "row and column headings and gridlines: the export draws the page as printed, without them",
        "hidden sheets: the export prints the sheets the workbook states as visible, and a created workbook states none",
        "a formula's own text: the export shows the value the reference computed from it",
    ],
    engine_computed: &[],
};
